//! Rendering the format tag registry into `docs/formats.md`.
//!
//! The registry in `syrox_encoding::formats` is the source of truth. `cargo xtask
//! formats` rewrites the reference and `cargo xtask check` rejects a stale copy.

use std::fmt::Write as _;
use std::fs;
use std::path::Path;

use syrox_encoding::formats::{ALL, Format};

const PATH: &str = "docs/formats.md";

const PREAMBLE: &str = "\
# Format tags

<!-- Generated by `cargo xtask formats` from crates/syrox-encoding/src/formats.rs; do not edit. -->

A format tag names the encoding of bytes that leave the code that produced
them: a record on disk, a message between processes, a hash domain or a
published identity. Every tag lives in `syrox_encoding::formats`; production
code references the registry and `cargo xtask check` rejects versioned tag
literals elsewhere. Tests and fixtures keep literal tags on purpose, as golden
checks that the registry still produces the same bytes.

## Versioning policy

- Bump a version only when a reader must tell old bytes from new ones: the
  layout or meaning of a persisted record changes, wire peers may run different
  builds, or digests in a hash domain must not collide with earlier digests.
  Bytes that never outlive one process, and additive changes the reader already
  rejects or ignores safely, need no new version.
- An unversioned tag is version 1. Its first incompatible change appends `-v2`.
- Changing a hash domain or identity tag changes every digest and identity
  derived from it. Treat that as a break of every stored pin, not a refactor.
- Add the previous tag to `reads` when bytes written by released versions must
  stay readable; the reader then handles each listed version explicitly. A
  writer may keep emitting an older version when it can represent the content
  (the lock and result manifests do this).
- Drop an old reader only when no supported installation can still hold those
  bytes, because a migration rewrote them or a release declared the break.
  Remove the tag from `reads` together with its parsing path.

## Boundaries

- **persisted**: written to disk and read back later, possibly by another version.
- **wire**: exchanged between cooperating processes or helpers during one operation.
- **hash domain**: only fed to a hasher; never stored as text.
- **identity**: part of a published content identity, catalog entry or contract name.

## Registry

| Tag | Boundary | Owner | Older versions read | Summary |
| --- | --- | --- | --- | --- |
";

fn cell(text: &str) -> String {
    text.replace('|', "\\|")
}

fn row(output: &mut String, format: &Format) {
    let reads = if format.reads.is_empty() {
        "-".to_owned()
    } else {
        format
            .reads
            .iter()
            .map(|tag| format!("`{tag}`"))
            .collect::<Vec<_>>()
            .join(", ")
    };
    writeln!(
        output,
        "| `{}` | {} | `{}` | {} | {} |",
        format.tag,
        format.boundary.name(),
        format.owner,
        reads,
        cell(format.summary)
    )
    .expect("writing to a String cannot fail");
}

pub(super) fn render() -> String {
    let mut output = String::from(PREAMBLE);
    for format in ALL {
        row(&mut output, format);
    }
    output
}

pub(super) fn write(root: &Path) -> std::io::Result<()> {
    fs::write(root.join(PATH), render())
}

pub(super) fn check(root: &Path) -> std::io::Result<()> {
    if fs::read_to_string(root.join(PATH))? == render() {
        Ok(())
    } else {
        Err(std::io::Error::other(format!(
            "{PATH} is stale; run cargo xtask formats"
        )))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_format_has_one_row() {
        let rendered = render();
        for format in ALL {
            assert_eq!(
                rendered
                    .lines()
                    .filter(|line| line.starts_with(&format!("| `{}` |", format.tag)))
                    .count(),
                1,
                "{}",
                format.tag
            );
        }
        assert!(rendered.contains("| `syrox-lock` | persisted |"));
    }
}
